const t=a?.threads.find(x=>x.id===a.activeId);
return {projectId:a?.projectId??null,activeId:a?.activeId??null,threads:(a?.threads??[]).length,busy:t?.busy??null,error:t?.error??null,
workPacket:t?.workPacket?{state:t.workPacket.state,objective:(t.workPacket.objective||'').slice(0,300),nextAction:t.workPacket.nextAction??null,pendingAction:t.workPacket.pendingAction??null,routingFailure:t.workPacket.routing?.failure??null}:null,
entries:(t?.entries??[]).map(e=>({kind:e.kind,tool:e.toolName??null,failed:e.failed??null,origin:e.executionOrigin??null,projectName:e.projectName??null,projectRevision:e.projectRevision??null,text:e.text}))}})();window.__qaBase={count:r.entries.length,kinds:r.entries.map(e=>e.kind)}}catch(e){window.__qaBase={count:-1,reason:String(e)}}};tick();return 'baseline'})()

(()=>{window.__qa=null;const END=Date.now()+600000;const tick=async()=>{try{const r=await (async()=>{const h=await import('/src/studio/assistant/chatHistory.ts');const a=await h.readChatArchive(window.__qaJob);
const t=a?.threads.find(x=>x.id===a.activeId);
return {projectId:a?.projectId??null,activeId:a?.activeId??null,threads:(a?.threads??[]).length,busy:t?.busy??null,error:t?.error??null,
workPacket:t?.workPacket?{state:t.workPacket.state,objective:(t.workPacket.objective||'').slice(0,300),nextAction:t.workPacket.nextAction??null,pendingAction:t.workPacket.pendingAction??null,routingFailure:t.workPacket.routing?.failure??null}:null,
entries:(t?.entries??[]).map(e=>({kind:e.kind,tool:e.toolName??null,failed:e.failed??null,origin:e.executionOrigin??null,projectName:e.projectName??null,projectRevision:e.projectRevision??null,text:e.text}))}})();
const base=(window.__qaBase&&window.__qaBase.count>=0)?window.__qaBase.count:0;const fresh=r.entries.slice(base);
if(r.busy){if(Date.now()>END){window.__qa={state:'timeout',baseline:base,...r};return}setTimeout(tick,1000);return}
if(fresh.some(e=>e.kind==='assistant')){window.__qa={state:r.error?'done-with-error':'done',baseline:base,newEntryCount:fresh.length,newEntries:fresh,...r};return}
if(r.error&&fresh.length){window.__qa={state:'error',baseline:base,newEntryCount:fresh.length,newEntries:fresh,...r};return}
if(Date.now()>END){window.__qa={state:'timeout',baseline:base,newEntryCount:fresh.length,newEntries:fresh,...r};return}
setTimeout(tick,1000)}catch(e){window.__qa={state:'threw',detail:String(e)}}};tick();return 'polling'})()

(()=>{const a=window.__qa;if(!a)throw Error('No turn archive');
const fresh=(a.newEntries||[]).length?a.newEntries:(a.entries||[]);
const rows=fresh.filter(e=>e.kind==='tool');
const reply=fresh.filter(e=>e.kind==='assistant').map(e=>e.text||'').join('\n\n');
return JSON.stringify({state:a.state,error:a.error??null,
tools:rows.map(r=>({tool:r.tool,failed:r.failed===true,text:(r.text||'').slice(0,300)})),
replyLength:reply.length})})()

(()=>{const a=window.__qa;if(!a)throw Error('No turn archive');
const fresh=(a.newEntries||[]).length?a.newEntries:(a.entries||[]);
const reply=fresh.filter(e=>e.kind==='assistant').map(e=>e.text||'').join('\n\n');
// The defect was that the answer was withheld and an error banner shown instead. Both halves are
// asserted: the answer is present, and no correction-limit error was raised.
if(!/LIVE TURN OK/.test(reply))throw Error('The requested three-word answer never reached the user. Reply: '+JSON.stringify(reply));
if(a.error)throw Error('The turn still failed: '+a.error);
if(/Workflow incomplete/.test(String(a.error||'')))throw Error('The unsatisfiable-workflow error is still raised for a tools-prohibited turn');
const rows=fresh.filter(e=>e.kind==='tool');
if(rows.length)throw Error('Tools ran although the user prohibited them: '+JSON.stringify(rows.map(r=>r.tool)));
return JSON.stringify({answerDelivered:true,workflowIncompleteError:false,toolsRun:0,replyLength:reply.length})})()

